+					link->dpcd_caps.dongle_type;
+				if (link->dpcd_caps.dongle_type ==
+						DISPLAY_DONGLE_DP_HDMI_CONVERTER)
+					apply_ch7218_pcon_caps_quirk(link);
 				break;
